#!/usr/bin/env python3
"""Writes src/base/encoding_tables.h from the WHATWG Encoding Standard's indexes.json and encodings.json
(https://encoding.spec.whatwg.org/indexes.json, .../encodings.json).

  python3 -I tools/gen_encoding_tables.py INDEXES.json ENCODINGS.json OUT.h
"""
import json
import sys


def main():
    indexes = json.load(open(sys.argv[1], encoding="utf-8"))
    groups = json.load(open(sys.argv[2], encoding="utf-8"))
    out = ["/* Generated by tools/gen_encoding_tables.py from the WHATWG Encoding Standard's indexes.json and",
           "   encodings.json. Do not edit. */", "#include <stdint.h>", ""]
    names, labels = [], []
    for g in groups:
        for e in g["encodings"]:
            names.append(e["name"])
            for label in e["labels"]:
                labels.append((label, len(names) - 1))
    labels.sort()
    out.append("enum {")
    for i, n in enumerate(names):
        out.append("    ENC_%s = %d," % (n.upper().replace("-", "_"), i))
    out.append("    ENC_COUNT = %d" % len(names))
    out.append("};")
    out.append("static const char *const enc_names[ENC_COUNT] = { %s };" % ", ".join('"%s"' % n for n in names))
    out.append("static const struct { const char *label; uint8_t enc; } enc_labels[%d] = {" % len(labels))
    out += ['    { "%s", %d },' % l for l in labels]
    out.append("};")

    def table(name, ctype, values, per=16):
        out.append("static const %s %s[%d] = {" % (ctype, name, len(values)))
        for i in range(0, len(values), per):
            out.append("    " + ",".join(str(v) for v in values[i:i + per]) + ",")
        out.append("};")

    sb = []
    for n in names:
        key = "iso-8859-8" if n == "ISO-8859-8-I" else n.lower()
        if key in indexes and len(indexes[key]) == 128:
            sb.append((n, key))
    out.append("/* the single-byte encodings: bytes 0x80-0xFF, 0 = no code point */")
    out.append("static const uint8_t enc_single_ids[%d] = { %s };" % (len(sb), ", ".join("ENC_" + n.upper().replace("-", "_") for n, _ in sb)))
    table("enc_single", "uint16_t", [v or 0 for _, key in sb for v in indexes[key]])
    for key, cname in [("jis0208", "idx_jis0208"), ("jis0212", "idx_jis0212"), ("euc-kr", "idx_euckr"), ("gb18030", "idx_gb18030")]:
        vals = [v or 0 for v in indexes[key]]
        assert max(vals) <= 0xFFFF
        table(cname, "uint16_t", vals)
    table("idx_big5", "uint32_t", [v or 0 for v in indexes["big5"]])
    table("idx_katakana", "uint16_t", indexes["iso-2022-jp-katakana"])
    ranges = indexes["gb18030-ranges"]
    table("idx_gb_ranges", "uint32_t", [x for r in ranges for x in r], 8)
    open(sys.argv[3], "w", encoding="utf-8").write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
